import { useCallback } from 'react';
import { useSelector } from 'react-redux';

import { FilterForm } from 'models/Filters';
import { RootState } from 'redux/types';

import { usePageFilterManagement } from '../usePageFilterManagement';

interface UseFilterAlertFallbackParams {
  pageName: string;
  key: string;
}

export const useFilterAlertFallback = ({
  pageName,
  key,
}: UseFilterAlertFallbackParams) => {
  const fallback = useSelector(
    (state: RootState) =>
      state.filters.pages[pageName]?.filterAlertFallbacks?.[key],
  );
  const {
    saveAlertFallback: save,
    dismissAlertFallback: dismiss,
    restoreAlertFallback: restore,
  } = usePageFilterManagement(pageName);

  const saveFallback = useCallback(
    (payload: {
      previousFilters?: FilterForm;
      lastValidFilters?: FilterForm;
      targetFilters?: FilterForm;
      targetKpi?: string;
      restoreStrategy:
        'previous-filters' | 'last-valid-filters' | 'page-defaults';
    }) => save({ key, ...payload }),
    [key, save],
  );

  const dismissFallback = useCallback(() => dismiss(key), [dismiss, key]);

  const restoreFallback = useCallback(() => restore(key), [key, restore]);

  return {
    fallback,
    saveFallback,
    dismissFallback,
    restoreFallback,
  };
};
